Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_add_digit_null_digit_malloc_failure(void) {
    // Setup: digit is NULL, we want malloc to fail
    big_int *digit = NULL;
    char value = '5';

    // Force the first malloc call to fail
    malloc_fail_next(1);

    // Test: add_digit with NULL digit should attempt malloc and fail
    big_int *result = add_digit(digit, value);

    // Assertions: Should return NULL due to allocation failure
    TEST_ASSERT_NULL(result);
    // No cleanup needed since allocation failed and nothing was allocated
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_add_digit_null_digit_malloc_failure);
    return UNITY_END();
}

